// 展示保存在当前浏览器的收藏和四章阅读进度。
import{crafts}from'../content/data.js';import{readStore,writeStore,toast}from'../main.js';
const holder=document.querySelector('#saved-collection');function render(){holder.replaceChildren();const ids=readStore('wenmai-saved',[]),saved=crafts.filter(c=>ids.includes(c.id));document.querySelector('#visited-summary').textContent=`你已循迹 ${crafts.filter(c=>readStore('wenmai-visited',[]).includes(c.id)).length}/4 章 · 已收藏 ${saved.length} 门技艺。`;if(!saved.length){holder.innerHTML='<div class="collection-empty"><p>你的百工册，还在等第一门手艺。到技艺页按“收藏此技艺”，便可留在这里。</p><a class="button quiet" href="./index.html#chapters">去四时百工寻一门手艺 ↗</a></div>';return;}for(const c of saved){const article=document.createElement('div');article.className='collection-item';article.innerHTML=`<img src="./assets/svg/${c.image}" alt="${c.name}纹样意象" width="80" height="65"><a href="./craft/${c.id}.html">${c.material} · ${c.name}</a><button class="pill" aria-label="取消收藏${c.name}">移出收藏</button>`;article.querySelector('button').addEventListener('click',()=>{if(writeStore('wenmai-saved',ids.filter(id=>id!==c.id))){render();toast('已移出百工收藏');}else toast('浏览器未允许更新本地存储');});holder.append(article);}}render();
